<?php
declare(strict_types=1);require_once __DIR__ . '/config/product_step12_bridge.php';
$error=null;$rows=[];$status=(string)($_GET['status']??'all');if(!in_array($status,['all','active','cancelled'],true))$status='all';$year=trim((string)($_GET['year']??'ALL'));$month=trim((string)($_GET['month']??'ALL'));
try{$pdo=business_db();product_step12_ensure($pdo);product_step12_bridge_backfill($pdo);$ctx=product_step12_context($pdo);$orgId=(int)$ctx['organization_id'];$rows=product_step12_sales_rows($pdo,$orgId,$status);$rows=array_values(array_filter($rows,static function($r)use($year,$month){$d=(string)$r['order_date'];if($year!=='ALL'&&substr($d,0,4)!==$year)return false;if($month!=='ALL'&&(int)substr($d,5,2)!==(int)$month)return false;return true;}));
 if(($_GET['format']??'')==='csv'){
  header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="product-sales-'.date('Ymd-His').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['Order','Date','Quote','Customer/Member','Sale Status','Net Revenue','VP','Payment Status','Paid','Outstanding','Cost Status','Verified Profit']);foreach($rows as $r){$outstanding=max(0,(float)$r['net_amount']-(float)$r['paid_amount']);fputcsv($out,[(int)$r['order_id'],$r['order_date'],$r['quote_code'],$r['member_name']?:$r['customer_name'],$r['sale_status'],number_format((float)$r['net_amount'],2,'.',''),number_format((float)$r['volume_points'],3,'.',''),$r['payment_status'],number_format((float)$r['paid_amount'],2,'.',''),number_format($outstanding,2,'.',''),$r['cost_status'],$r['profit_total']===null?'':number_format((float)$r['profit_total'],2,'.','')]);}fclose($out);exit;
 }
}catch(Throwable $e){$error=$e->getMessage();}
function pse_money(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?>
