<header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 12 • Product Sales Export</small></span></a><div class="os-top-actions"><a class="os-btn" href="product_sales_center.php">Sales</a><button class="os-btn" onclick="window.print()">Print / Save PDF</button><a class="os-btn primary" href="?<?= product_h(http_build_query(['status'=>$status,'year'=>$year,'month'=>$month,'format'=>'csv'])) ?>">Export CSV</a></div></div></header>
<div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">STEP 12</div><nav class="os-nav"><a href="product_sales_center.php"><i class="dot"></i>Sales Center</a><a href="product_sales_analytics.php"><i class="dot"></i>Sales Analytics</a><a class="active" href="product_sales_export.php"><i class="dot"></i>Export / Share</a><a href="step12_audit.php"><i class="dot"></i>STEP 12 Audit</a></nav></aside><main class="os-main"><section class="os-hero pp-hero no-print"><div class="os-kicker">STEP 12I • EXPORT & SHARE</div><h1>Export the same filtered Product Sales facts you see on screen.</h1><p>CSV uses UTF-8 and Print can be saved as PDF. Cancelled rows remain identifiable and verified profit stays blank when cost coverage is incomplete.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'PRODUCT SALES EXPORT LIVE':'Review required' ?></span><span class="os-chip"><?= count($rows) ?> visible sales</span></div></section><?php if($error):?><div class="pp-alert bad"><?= product_h($error) ?></div><?php else:?><section class="os-card no-print" style="margin-top:14px"><form method="get" class="pp-toolbar"><select name="status"><option value="all" <?= $status==='all'?'selected':'' ?>>All Status</option><option value="active" <?= $status==='active'?'selected':'' ?>>Active</option><option value="cancelled" <?= $status==='cancelled'?'selected':'' ?>>Cancelled</option></select><input name="year" value="<?= product_h($year) ?>" placeholder="Year or ALL"><input name="month" value="<?= product_h($month) ?>" placeholder="Month 1-12 or ALL"><button>Apply</button></form></section><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Product Sales Register</h2><p>Status <?= product_h(strtoupper($status)) ?> • Year <?= product_h($year) ?> • Month <?= product_h($month) ?></p></div></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Order</th><th>Date</th><th>Customer</th><th>Status</th><th>Revenue</th><th>VP</th><th>Payment</th><th>Paid</th><th>Outstanding</th><th>Cost</th><th>Verified Profit</th></tr></thead><tbody><?php foreach($rows as $r):$out=max(0,(float)$r['net_amount']-(float)$r['paid_amount']);?><tr><td>#<?= (int)$r['order_id'] ?><small><?= product_h($r['quote_code']?:'') ?></small></td><td><?= product_h($r['order_date']) ?></td><td><?= product_h($r['member_name']?:$r['customer_name']?:'—') ?></td><td><?= product_h(strtoupper($r['sale_status'])) ?></td><td><?= pse_money($r['net_amount']) ?></td><td><?= product_h($r['volume_points']) ?></td><td><?= product_h(strtoupper($r['payment_status'])) ?></td><td><?= pse_money($r['paid_amount']) ?></td><td><?= pse_money($out) ?></td><td><?= product_h(strtoupper($r['cost_status'])) ?></td><td><?= $r['profit_total']===null?'—':pse_money($r['profit_total']) ?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="11">No Product Sales match this filter.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
